import { test, expect } from '@playwright/test';

test.describe('Session Expiration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/login');
    await page.fill('input[name="username"]', 'testuser');
    await page.fill('input[name="password"]', 'password123');
    await page.click('button[type="submit"]');
    await expect(page.getByText('Welcome, testuser')).toBeVisible();
  });

  test('should expire session after 30 minutes of inactivity', async ({ page }) => {
    await page.waitForTimeout(30 * 60 * 1000); // Wait for 30 minutes
    await page.reload();
    await expect(page.getByText('Your session has expired. Please log in again.')).toBeVisible();
  });

  test('should remain logged in if activity occurs before session expiration', async ({ page }) => {
    await page.waitForTimeout(29 * 60 * 1000); // Wait for 29 minutes
    await page.click('button#some-action'); // Simulate user activity
    await expect(page.getByText('Welcome, testuser')).toBeVisible();
    await page.waitForTimeout(1 * 60 * 1000); // Wait for 1 more minute
    await page.reload();
    await expect(page.getByText('Welcome, testuser')).toBeVisible();
  });
});
